1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUMS: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	};
7	
8	const COMPONENT_BASE_PREMIUM = 25;
9	const COMPONENT_BLOCK_SIZE = 3;
10	const COMPONENT_BLOCK_PREMIUM = 60;
11	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
12	
13	const FIRST_INSURANCE_SURCHARGE = 0.1;
14	const CURSE_SURCHARGE = 0.5;
15	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
16	const HIGH_ENCHANTMENT_THRESHOLD = 5;
17	const LOYALTY_DISCOUNT = 0.2;
18	const LOYALTY_YEARS_THRESHOLD = 2;
19	const FOLLOWUP_CONTRACT_DISCOUNT = 0.15;
20	
21	const INSURANCE_VALUES: Record<string, number> = {
22	  sword: 1000,
23	  amulet: 600,
24	  rune: 250,
25	  moonstone: 250,
26	};
27	
28	const DEDUCTIBLE = 100;
29	const CAP_MULTIPLIER = 2;
30	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
31	const HALF_REIMBURSEMENT = 0.5;
32	const FULL_REIMBURSEMENT = 1;
33	
34	interface Item {
35	  type: string;
36	  cursed?: boolean;
37	  enchantment?: number;
38	}
39	
40	interface QuoteStep {
41	  op: "quote";
42	  items: Item[];
43	}
44	
45	interface Damage {
46	  itemType: string;
47	  amount: number;
48	}
49	
50	interface ClaimStep {
51	  op: "claim";
52	  policy: number;
53	  incident: { cause: string; damages: Damage[] };
54	}
55	
56	type Step = QuoteStep | ClaimStep;
57	
58	interface Customer {
59	  yearsWithMHPCO: number;
60	}
61	
62	interface Scenario {
63	  customer: Customer;
64	  steps: Step[];
65	}
66	
67	interface QuoteResult {
68	  premium: number;
69	}
70	
71	interface ClaimResult {
72	  payout: number;
73	  remainingCap: number;
74	}
75	
76	type StepResult = QuoteResult | ClaimResult;
77	
78	interface ScenarioResult {
79	  results: StepResult[];
80	}
81	
82	const componentGroupBase = (count: number): number =>
83	  count === COMPONENT_BLOCK_SIZE
84	    ? COMPONENT_BLOCK_PREMIUM
85	    : count * COMPONENT_BASE_PREMIUM;
86	
87	const countBy = <T>(elements: T[], keyOf: (element: T) => string): Map<string, number> => {
88	  const counts = new Map<string, number>();
89	  for (const element of elements) {
90	    const key = keyOf(element);
91	    counts.set(key, (counts.get(key) ?? 0) + 1);
92	  }
93	  return counts;
94	};
95	
96	const countByType = (items: Item[]): Map<string, number> =>
97	  countBy(items, (item) => item.type);
98	
99	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
100	
101	const isHighEnchantment = (item: Item): boolean =>
102	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
103	
104	interface PricedUnit {
105	  base: number;
106	  surcharges: number[];
107	}
108	
109	// Per-item surcharge rules on a main item, each a fraction of the item base
110	// applied when its condition holds. New surcharges are added as list entries.
111	const mainItemSurchargeRules: { applies: (item: Item) => boolean; rate: number }[] = [
112	  { applies: (item) => item.cursed === true, rate: CURSE_SURCHARGE },
113	  { applies: isHighEnchantment, rate: HIGH_ENCHANTMENT_SURCHARGE },
114	];
115	
116	const mainItemUnit = (item: Item): PricedUnit => {
117	  const base = BASE_PREMIUMS[item.type];
118	  const surcharges = mainItemSurchargeRules
119	    .filter((rule) => rule.applies(item))
120	    .map((rule) => base * rule.rate);
121	  return { base, surcharges };
122	};
123	
124	const componentUnit = (count: number): PricedUnit => ({
125	  base: componentGroupBase(count),
126	  surcharges: [],
127	});
128	
129	const pricedUnits = (items: Item[]): PricedUnit[] => {
130	  const mainUnits = items.filter((item) => !isComponent(item)).map(mainItemUnit);
131	
132	  const components = items.filter(isComponent);
133	  const componentUnits = [...countByType(components).values()].map(componentUnit);
134	
135	  return [...mainUnits, ...componentUnits];
136	};
137	
138	const unitTotal = (unit: PricedUnit): number =>
139	  unit.base +
140	  unit.base * FIRST_INSURANCE_SURCHARGE +
141	  unit.surcharges.reduce((sum, surcharge) => sum + surcharge, 0);
142	
143	// Policy-level discount fractions applied to the policy base (sum of unit bases).
144	// Each entry that applies contributes its fraction; new modifiers (e.g. follow-up
145	// contract discount) can be added here without touching per-item pricing.
146	const policyBaseDiscountFractions = (customer: Customer, isFollowUp: boolean): number[] => {
147	  const fractions: number[] = [];
148	  if (customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD) fractions.push(LOYALTY_DISCOUNT);
149	  if (isFollowUp) fractions.push(FOLLOWUP_CONTRACT_DISCOUNT);
150	  return fractions;
151	};
152	
153	const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
154	  const units = pricedUnits(items);
155	  const itemsTotal = units.reduce((sum, unit) => sum + unitTotal(unit), 0);
156	  const policyBase = units.reduce((sum, unit) => sum + unit.base, 0);
157	  const policyDiscount = policyBaseDiscountFractions(customer, isFollowUp).reduce(
158	    (sum, fraction) => sum + policyBase * fraction,
159	    0,
160	  );
161	  return Math.ceil(itemsTotal - policyDiscount + PROCESSING_FEE);
162	};
163	
164	interface Policy {
165	  items: Item[];
166	  remainingCap: number;
167	}
168	
169	const createPolicy = (items: Item[]): Policy => {
170	  const insuranceSum = items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
171	  return { items, remainingCap: insuranceSum * CAP_MULTIPLIER };
172	};
173	
174	// Fraction of a damage amount the policy reimburses, before the deductible.
175	// Coverage clauses (e.g. dragon-material full reimbursement) will add branches here.
176	const reimbursementRate = (item: Item | undefined): number =>
177	  (item?.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
178	    ? HALF_REIMBURSEMENT
179	    : FULL_REIMBURSEMENT;
180	
181	const reimbursedAmount = (item: Item | undefined, amount: number): number =>
182	  amount * reimbursementRate(item);
183	
184	const damagePayout = (policy: Policy, damage: Damage): number => {
185	  const item = policy.items.find((candidate) => candidate.type === damage.itemType);
186	  return reimbursedAmount(item, damage.amount) - DEDUCTIBLE;
187	};
188	
189	const validateDamageCounts = (policy: Policy, damages: Damage[]): void => {
190	  const insured = countByType(policy.items);
191	  const damaged = countBy(damages, (damage) => damage.itemType);
192	  for (const [itemType, count] of damaged) {
193	    if (count > (insured.get(itemType) ?? 0)) {
194	      throw new Error(`claim damages more ${itemType} than insured`);
195	    }
196	  }
197	};
198	
199	const desiredPayout = (policy: Policy, damages: Damage[]): number =>
200	  damages.reduce((sum, damage) => sum + damagePayout(policy, damage), 0);
201	
202	const processClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
203	  validateDamageCounts(policy, damages);
204	  const payout = Math.min(Math.floor(desiredPayout(policy, damages)), policy.remainingCap);
205	  policy.remainingCap -= payout;
206	  return { payout, remainingCap: policy.remainingCap };
207	};
208	
209	export const runScenario = (scenario: Scenario): ScenarioResult => {
210	  const policies: Policy[] = [];
211	  let quoteCount = 0;
212	
213	  const handleQuote = (step: QuoteStep): QuoteResult => {
214	    const isFollowUp = quoteCount > 0;
215	    quoteCount += 1;
216	    policies.push(createPolicy(step.items));
217	    return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
218	  };
219	
220	  const handleClaim = (step: ClaimStep): ClaimResult =>
221	    processClaim(policies[step.policy], step.incident.damages);
222	
223	  const results = scenario.steps.map((step): StepResult =>
224	    step.op === "quote" ? handleQuote(step) : handleClaim(step),
225	  );
226	  return { results };
227	};
